#[derive(Clone, Serialize, Deserialize)]
#[serde(into = "MareyTileNoCache", from = "MareyTileNoCache")]
pub(crate) struct MareyTile {
    key: RouteKey,
    navi: MareyTileNavigation,
    cache: MareyCache,
    callback: gpu_draw::MareyCallback,
    /// We store the world to compare the cache. World is just a set of shared pointers so it is
    /// relatively cheap
    prev_world: Option<World>,
}

/// [`MareyTile`] w/o cache for serde
#[derive(Clone, Serialize, Deserialize)]
struct MareyTileNoCache {
    key: RouteKey,
    navi: MareyTileNavigation,
}

impl From<MareyTile> for MareyTileNoCache {
    fn from(MareyTile { key, navi, .. }: MareyTile) -> Self {
        Self { key, navi }
    }
}

impl From<MareyTileNoCache> for MareyTile {
    fn from(MareyTileNoCache { key, navi }: MareyTileNoCache) -> Self {
        Self {
            key,
            navi,
            cache: MareyCache::default(),
            callback: gpu_draw::MareyCallback::new(key),
            prev_world: None,
        }
    }
}

impl MareyTile {
    pub fn new(key: RouteKey) -> Self {
        Self {
            key,
            navi: MareyTileNavigation::default(),
            cache: MareyCache::default(),
            callback: gpu_draw::MareyCallback::new(key),
            prev_world: None,
        }
    }
    fn update_cache(&mut self, curr_world: &World) {
        puffin::profile_function!();
        let Some(curr_route) = curr_world.routes.get(&self.key) else {
            return;
        };
        // TODO: reuse MareyCache
        let (_rebuild_route, trips_to_rebuild) = match self.prev_world.as_ref() {
            None => (
                true,
                Either::Left(curr_route.intervals.all_passing_trips(curr_world).into_iter()),
            ),
            Some(prev_world) => {
                let rebuild_route = prev_world.graph.nodes().ptr_eq(curr_world.graph.nodes())
                    || prev_world.graph.intervals().ptr_eq(curr_world.graph.intervals())
                    || prev_world.routes.get(&self.key) != Some(curr_route);
                let trips_to_rebuild =
                    prev_world.trips.diff(&curr_world.trips).map(|diff| match diff {
                        DiffItem::Add(key, _)
                        | DiffItem::Remove(key, _)
                        | DiffItem::Update { old: (key, _), .. } => *key,
                    });
                (rebuild_route, Either::Right(trips_to_rebuild))
            }
        };
        curr_route.intervals.populate_trips(curr_world, &mut self.cache, trips_to_rebuild);
        self.prev_world = Some(curr_world.clone());
    }
}

impl PartialEq for MareyTile {
    fn eq(&self, other: &Self) -> bool {
        self.key == other.key
    }
}

#[derive(Clone, Serialize, Deserialize)]
struct MareyTileNavigation {
    x_offset: Tick,
    y_offset: CanvasLength,
    zoom: Vec2,
    #[serde(skip, default = "default_visible_rect")]
    visible_rect: Rect,
    #[serde(skip, default)]
    max_height: CanvasLength,
}

impl Default for MareyTileNavigation {
    fn default() -> Self {
        // Default horizontal scale: five minutes of time span one centimetre of canvas.
        let five_minutes_in_ticks = TimetableTime::from_hms(0, 5, 0).to_ticks().0 as f32;
        let one_cm_in_pts = CanvasLength::from_cm(1.0).to_egui_pts();
        Self {
            x_offset: Tick(0),
            y_offset: CanvasLength(0.0),
            zoom: vec2(one_cm_in_pts / five_minutes_in_ticks, 1.0),
            visible_rect: Rect::NOTHING,
            max_height: CanvasLength(0.0),
        }
    }
}

fn default_visible_rect() -> Rect {
    Rect::NOTHING
}

impl Navigatable for MareyTileNavigation {
    type XOffset = Tick;
    type YOffset = CanvasLength;

    fn zoom_x(&self) -> f32 {
        self.zoom.x
    }
    fn zoom_y(&self) -> f32 {
        self.zoom.y * CanvasLength::egui_pts_per_mm() as f32
    }
    fn set_zoom(&mut self, zoom_x: f32, zoom_y: f32) {
        self.zoom = Vec2::new(zoom_x, zoom_y / CanvasLength::egui_pts_per_mm() as f32);
    }
    fn offset_x(&self) -> f64 {
        self.x_offset.0 as f64
    }
    fn offset_y(&self) -> f64 {
        self.y_offset.0
    }
    fn set_offset(&mut self, offset_x: f64, offset_y: f64) {
        self.x_offset = Tick(offset_x.round() as i64);
        self.y_offset = CanvasLength(offset_y);
    }
    fn visible_rect(&self) -> egui::Rect {
        self.visible_rect
    }
    fn allow_axis_zoom(&self) -> bool {
        true
    }
    fn clamp_zoom(&self, zoom_x: f32, zoom_y: f32) -> (f32, f32) {
        let ppmm = CanvasLength::egui_pts_per_mm() as f32;
        (
            zoom_x.clamp(0.00005, 0.4),
            zoom_y.clamp(ppmm * 0.1, ppmm * 2048.0),
        )
    }
    fn post_navigation(&mut self, response: &egui::Response) {
        let max_tick = Tick::from_timetable_time(TimetableTime(366 * 86400)).0;
        self.x_offset = Tick(self.x_offset.0.clamp(
            -max_tick,
            max_tick - (response.rect.width() as f64 / self.zoom.x as f64) as i64,
        ));
        const TOP_BOTTOM_PADDING: f32 = 30.0;
        let v = if response.rect.height() / self.zoom_y()
            > (self.max_height.0 as f32 + TOP_BOTTOM_PADDING * 2.0 / self.zoom_y())
        {
            ((-response.rect.height() / self.zoom_y() + self.max_height.0 as f32) / 2.0) as f64
        } else {
            self.y_offset.0.clamp(
                (-TOP_BOTTOM_PADDING / self.zoom_y()) as f64,
                (self.max_height.0 as f32 - response.rect.height() / self.zoom_y()
                    + TOP_BOTTOM_PADDING / self.zoom_y()) as f64,
            )
        };
        self.y_offset.0 = v;
    }
}

impl Tile for MareyTile {
    const NAME: &'static str = "Marey Diagram";
    fn title(&self) -> WidgetText {
        Self::NAME.into()
    }
    fn main_display(&mut self, app: &mut App, ui: &mut Ui) {
        puffin::profile_function!();
        self.update_cache(app);
        self.callback.populate_entry_segments(&self.cache, &app);
        let Some(route) = app.routes.get(&self.key) else {
            ui.centered_and_justified(|ui| ui.heading("Route does not exist"));
            self.cache.map.clear();
            return;
        };
        let window = Window::new("123")
            .id(ui.scope_id().with("123"))
            .auto_sized()
            .title_bar(false)
            .fixed_pos(ui.clip_rect().shrink(8.0).right_top())
            .pivot(Align2::RIGHT_TOP);
        window.show(ui.ctx(), |ui: &mut Ui| {
            if ui.button("Export PDF").clicked() {
                let fonts = ui.fonts(|fonts| {
                    let mut ret = Vec::new();
                    let defs = fonts.definitions();
                    if let Some(names) = defs.families.get(&egui::FontFamily::Proportional) {
                        for name in names {
                            let blob = &defs.font_data[name].font;
                            let bytes: &[u8] = (**blob).as_ref();
                            ret.push(std::borrow::Cow::Owned(bytes.to_vec()))
                        }
                    }
                    ret
                });
                paiagram_export::ExportGraphy {
                    world: app.world.clone(),
                    route: self.key,
                    cache: self.cache.clone(),
                    format: GraphyFormat::Pdf,
                    fonts,
                }
                .write_via_interface(app.file_write_tx.clone());
            }
        });
        Frame::canvas(ui.style())
            .inner_margin(Margin::ZERO)
            .outer_margin(Margin::ZERO)
            .stroke(Stroke::NONE)
            .show(ui, |ui| {
                main_display(self, app, ui);
            });
    }
}

fn draw_time_lines(painter: &mut Painter, navi: &MareyTileNavigation) {
    puffin::profile_function!();
    const MAX_SCREEN_WIDTH: f64 = 64.0;
    const MIN_SCREEN_WIDTH: f64 = 32.0;
    let sizes = [
        Tick::from_timetable_time(TimetableTime(1)).0, // 1 second
        Tick::from_timetable_time(TimetableTime(10)).0, // 10 seconds
        Tick::from_timetable_time(TimetableTime(30)).0, // 30 seconds
        Tick::from_timetable_time(TimetableTime(60)).0, // 1 minute
        Tick::from_timetable_time(TimetableTime(60 * 5)).0, // 5 minutes
        Tick::from_timetable_time(TimetableTime(60 * 10)).0, // 10 minutes
        Tick::from_timetable_time(TimetableTime(60 * 30)).0, // 30 minutes
        Tick::from_timetable_time(TimetableTime(60 * 60)).0, // 1 hour
        Tick::from_timetable_time(TimetableTime(60 * 60 * 4)).0, // 4 hours
        Tick::from_timetable_time(TimetableTime(60 * 60 * 24)).0, // 1 day
    ];
    let visible_ticks = navi.visible_x();
    let ticks_per_screen_unit = navi.x_per_screen_unit_f64();
    let screen_rect = navi.visible_rect();
    let pixels_per_point = painter.pixels_per_point();
    let mut drawn: Vec<i64> = Vec::with_capacity(30);

    // align the first tick to a spacing boundary that is <= visible start.
    let first_visible_position = sizes
        .iter()
        .position(|s| *s as f64 / ticks_per_screen_unit * 1.5 > MIN_SCREEN_WIDTH)
        .unwrap_or(0);
    let visible = &sizes[first_visible_position..];
    for (i, spacing) in visible.iter().enumerate().rev() {
        let first = visible_ticks.start.0 - visible_ticks.start.0.rem_euclid(*spacing) - spacing;
        let mut tick = first;
        let strength = (((*spacing as f64 / ticks_per_screen_unit * 1.5) - MIN_SCREEN_WIDTH)
            / (MAX_SCREEN_WIDTH - MIN_SCREEN_WIDTH))
            .clamp(0.0, 1.0);
        if strength < 0.1 {
            continue;
        }
        // TODO: make stroke depend on current theme
        let mut current_stroke = Stroke {
            width: 0.6,
            color: Color32::GRAY,
        };
        if strength.is_finite() {
            // strange bug here
            current_stroke.color = current_stroke.color.gamma_multiply(strength as f32);
        }
        current_stroke.width = 0.5;
        while tick <= visible_ticks.end.0 {
            tick += *spacing;
            if drawn.contains(&tick) {
                continue;
            }
            let mut x = navi.logical_x_to_screen_x(Tick(tick));
            current_stroke.round_center_to_pixel(pixels_per_point, &mut x);
            painter.vline(x, screen_rect.top()..=screen_rect.bottom(), current_stroke);
            drawn.push(tick);
            let time = Tick(tick).to_timetable_time();
            let mut offset = screen_rect.top();
            let text = match i + first_visible_position {
                0..=2 => time.to_hmsd().2.to_string(),
                3..=8 => format!("{}:{:02}", time.to_hmsd().0, time.to_hmsd().1),
                9 => {
                    offset += 13.0;
                    time.to_string()
                }
                _ => unreachable!(),
            };
            painter.text(
                Pos2 { x, y: offset },
                Align2::CENTER_TOP,
                text,
                FontId::proportional(13.0),
                current_stroke.color,
            );
        }
    }
}

fn main_display(tile: &mut MareyTile, app: &mut App, ui: &mut Ui) {
    puffin::profile_function!();
    let (response, mut painter) =
        ui.allocate_painter(ui.available_size_before_wrap(), Sense::click_and_drag());
    tile.navi.visible_rect = response.rect;
    tile.navi.handle_navigation(ui, &response);

    draw_time_lines(&mut painter, &tile.navi);

    let Some(route) = app.routes.get(&tile.key).cloned() else {
        return;
    };

    let (station_heights, max_height) = route.intervals.0.iter().fold(
        (
            Vec::with_capacity(route.intervals.0.len()),
            CanvasLength::ZERO,
        ),
        |(mut acc, height_so_far), interval| {
            let Some(station) = interval
                .station_record
                .station_key(app.graph.nodes())
                .and_then(|key| app.stations.get(key))
            else {
                return (acc, height_so_far);
            };
            let station_line_stroke = Stroke {
                width: 0.6,
                color: Color32::GRAY,
            };
            let mut y = tile.navi.logical_y_to_screen_y(height_so_far);
            station_line_stroke.round_center_to_pixel(ui.pixels_per_point(), &mut y);
            painter.hline(response.rect.x_range(), y, station_line_stroke);
            painter.text(
                pos2(response.rect.left(), y),
                Align2::LEFT_BOTTOM,
                station.name.as_str(),
                FontId::proportional(13.0),
                station_line_stroke.color,
            );
            acc.push(height_so_far);
            (
                acc,
                height_so_far + interval.canvas_length.unwrap_or(CanvasLength::from_cm(1.5)),
            )
        },
    );

    tile.navi.max_height = max_height;

    // paint the station lines and Marey lines
    tile.callback.populate_stations(station_heights.iter().copied());
    tile.callback.populate_uniforms(&tile.navi, response.rect);
    painter.add(tile.callback.clone().paint_callback(response.rect));

    // current time overlay
    {
        let seconds = app.timer.seconds();
        let mut x = tile.navi.logical_x_to_screen_x(Tick::from_seconds_f64(seconds));
        let stroke = Stroke::new(2.0, Color32::RED);
        stroke.round_center_to_pixel(ui.pixels_per_point(), &mut x);
        painter.vline(x, response.rect.y_range(), stroke);
        let range = Rangef::point(x).expand(5.0);
        painter.hline(range, response.rect.bottom() - stroke.width / 2.0, stroke);
        painter.hline(range, response.rect.top() + stroke.width / 2.0, stroke);
    }

    // selected item overlay
    let animation_progress = ui.animate_bool_responsive(
        ui.scope_id().with("ui animation progress"),
        !matches!(app.selected_items, SelectedItems::None),
    );
    painter.rect_filled(
        response.rect,
        0,
        ui.visuals().extreme_bg_color.gamma_multiply(lerp(0.0..=0.5, animation_progress)),
    );

    // interactive zone
    if response.clicked()
        && let Some(pointer_pos) = response.interact_pointer_pos()
        // this makes sure that when already selecting item
        // the next action always deselects the item instead of focusing on new item
        && !matches!(app.selected_items, SelectedItems::TripExtension(_)) // it has its own state
        && matches!(app.selected_items.take(), SelectedItems::None)
    {
        if let Some(trip_key) = select_trip_from_pos(tile, pointer_pos, &station_heights) {
            app.selected_items.replace(SelectedItem::Trip(trip_key.into()));
        } else if response.double_clicked()
            // TODO: also show the route when hovering in another trip panel?
            && let Some(station_idx) = find_nearest_station_idx_from_pos(&station_heights, pointer_pos, &tile.navi)
            && let interval = &route.intervals.0[station_idx]
            && let Some(station_key) = interval.station_record.station_key(app.graph.nodes())
            && let Some(station) = app.stations.get(station_key)
            && let Some(node) = station.cache.nodes.first()
        {
            let t = tile.navi.screen_x_to_logical_x(pointer_pos.x).to_timetable_time();
            let trip_key = TripKey::new();
            let id = TEntryId::new();
            let new_entry = TEntry {
                node: *node,
                arr_or_pass: TravelMode::At(t),
                dep: None,
                id,
            };
            let _ = app.mutate(|mut world| {
                world.trips.insert(
                    trip_key,
                    Wfc::new(Trip {
                        name: "New Trip".into(),
                        schedule: TripSchedule::new(eco_vec![new_entry]),
                        service_class: None,
                        vehicles: Default::default(),
                    }),
                );
                Ok(world)
            });
            app.selected_items = SelectedItems::TripExtension((trip_key, None));
        }
    }

    // display and edit zone
    if matches!(app.selected_items, SelectedItems::Trips(_))
        && let SelectedItems::Trips(mut trips) = app.selected_items.take()
    {
        for selected in trips.iter_mut() {
            let trip_key = &selected.trip_key;
            let Some(trip) = app.trips.get(trip_key) else {
                continue;
            };
            let style = trip
                .service_class
                .and_then(|key| app.service_classes.get(&key))
                .map_or_default(|class| class.style);
            let stroke = Stroke {
                width: lerp(style.width as f32..=5.0, animation_progress),
                color: style.color,
            };
            let schedule = trip.schedule.clone().with_entry_shift(selected.editing_offset);
            let Some(polylines) = route.intervals.populate_schedule(&app.world, &schedule) else {
                continue;
            };
            let polylines = polylines.clone();
            let ret = show_focused_trips::show_focused_trip(
                &schedule,
                stroke,
                &mut app.source,
                animation_progress,
                ui,
                tile,
                &station_heights,
                &mut painter,
                polylines,
                *trip_key,
                selected.editing_offset.map(|it| it.1),
            );
            selected.editing_offset = ret;
        }
        app.selected_items = SelectedItems::Trips(trips);
    } else if let &SelectedItems::TripExtension((trip_key, focused_pos)) = &app.selected_items
        && let Some(trip) = app.trips.get(&trip_key)
    {
        let stroke = Stroke::new(3.0, Color32::RED);

        let focused_pos = if let Some(pointer_pos) = ui.pointer_hover_pos()
            && let Some(station_idx) =
                find_nearest_station_idx_from_pos(&station_heights, pointer_pos, &tile.navi)
            && let Some(interval) = route.intervals.0.get(station_idx)
            && let Some(station_key) = interval.station_record.station_key(app.graph.nodes())
            && let Some(station) = app.stations.get(station_key)
            && let Some(node) = station.cache.nodes.first()
        {
            Some((
                *node,
                tile.navi.screen_x_to_logical_x(pointer_pos.x).to_timetable_time(),
            ))
        } else {
            focused_pos
        };

        let schedule = trip.schedule.clone().with_pushed_entry(focused_pos);

        if response.clicked()
            && let Some((focused_node, focused_time)) = focused_pos
        {
            let _ = app.mutate(|mut world| {
                let trip = world.trips.get_mut(&trip_key).ok_or("wtf?")?;
                trip.schedule.push(TEntry {
                    node: focused_node,
                    arr_or_pass: TravelMode::At(focused_time),
                    dep: None,
                    id: TEntryId::new(),
                });
                Ok(world)
            });
        }

        route.intervals.populate_schedule(&app.world, &schedule).into_iter().flatten().for_each(
            |polyline| {
                draw_polyline(
                    &tile.navi,
                    &polyline,
                    &station_heights,
                    &mut painter,
                    stroke,
                );
            },
        );

        app.selected_items = SelectedItems::TripExtension((trip_key, focused_pos));

        if response.secondary_clicked() {
            app.selected_items = SelectedItems::None;
        }
    }
    if let Some(pos) = ui.pointer_hover_pos()
        && ui.ui_contains_pointer()
    {
        paint_time_cursor(
            &tile.navi,
            &station_heights,
            pos,
            ui,
            response.rect,
            route,
            app,
        );
    }
}

fn select_trip_from_pos(
    tile: &MareyTile,
    ptr_pos: Pos2,
    station_heights: &[CanvasLength],
) -> Option<TripKey> {
    puffin::profile_function!();
    const SELECT_RADIUS: f32 = 7.0;
    // The same point mapping as when drawing (see the display zone in `main_display`), so that
    // what is selected matches what is drawn. Each entry spans `arr`..`dep` at one placement.
    let points = |estimate: &TEstimate, idx: u32, progress: f32| {
        let x1 = tile.navi.logical_x_to_screen_x(estimate.arr.to_ticks());
        let x2 = tile.navi.logical_x_to_screen_x(estimate.dep.to_ticks());
        let curr_y = tile.navi.logical_y_to_screen_y(station_heights[idx as usize]);
        let next_y = tile.navi.logical_y_to_screen_y(station_heights[idx as usize + 1]);
        let y = lerp(curr_y..=next_y, progress);
        [Pos2::new(x1, y), Pos2::new(x2, y)]
    };
    let hit = |p1: Pos2, p2: Pos2| {
        let diff = p2 - p1;
        let len_sq = diff.length_sq();
        let t = if len_sq > 0.0 {
            ((ptr_pos - p1).dot(diff) / len_sq).clamp(0.0, 1.0)
        } else {
            0.0
        };
        (p1 + t * diff - ptr_pos).length_sq() <= SELECT_RADIUS * SELECT_RADIUS
    };

    tile.cache
        .map
        .iter()
        .flat_map(|(k, v)| v.iter().map(move |l| (k, l)))
        .flat_map(|(k, l)| l.array_windows().map(move |w| (k, w)))
        .find_map(|(key, [curr, next])| {
            let [curr_arr, curr_dep] = points(&curr.0, curr.2, curr.3);
            let [next_arr, next_dep] = points(&next.0, next.2, next.3);
            // The segments the drawing produces between two consecutive entries: the dwell at
            // the first, the travel between them, and the dwell at the second.
            (hit(curr_arr, curr_dep) || hit(curr_dep, next_arr) || hit(next_arr, next_dep))
                .then_some(*key)
        })
}

fn find_nearest_station_idx_from_pos(
    station_heights: &[CanvasLength],
    pos: Pos2,
    navi: &MareyTileNavigation,
) -> Option<usize> {
    if station_heights.is_empty() {
        return None;
    }
    let target_y = navi.screen_y_to_logical_y(pos.y);
    let idx = station_heights.partition_point(|&height| height < target_y);

    if idx == 0 {
        Some(0)
    } else if idx >= station_heights.len() {
        Some(station_heights.len() - 1)
    } else {
        let prev = station_heights[idx - 1];
        let next = station_heights[idx];
        let mid = CanvasLength((prev.0 + next.0) / 2.0);

        if target_y <= mid {
            Some(idx - 1)
        } else {
            Some(idx)
        }
    }
}

fn paint_time_cursor(
    navi: &MareyTileNavigation,
    station_heights: &[CanvasLength],
    pointer_pos: Pos2,
    ui: &mut Ui,
    rect: Rect,
    route: Wfc<Route, RouteCache>,
    app: &App,
) {
    let stroke = Stroke::new(1.5, Color32::RED);
    let (pointer_t, pointer_distance) = navi.screen_pos_to_xy(pointer_pos);
    let Some(station_idx) = find_nearest_station_idx_from_pos(station_heights, pointer_pos, navi)
    else {
        return;
    };
    let dt = ui.input(|input| input.stable_dt).at_most(0.1);
    let mut requires_repaint = false;
    let new_logical_y = station_heights[station_idx];
    let smoothed_logical_y = ui.data_mut(|data| {
        let smoothed: &mut CanvasLength =
            data.get_temp_mut_or(ui.scope_id().with("pointer animation"), new_logical_y);
        let t = emath::exponential_smooth_factor(0.9, 0.05, dt);
        *smoothed = CanvasLength(lerp(smoothed.0..=new_logical_y.0, t as f64));
        if (*smoothed - new_logical_y).0.abs() < 0.5 {
            requires_repaint = true;
        }
        *smoothed
    });
    if requires_repaint {
        ui.request_repaint();
    }
    // time axis snaps, station axis animates
    let mut pos =
        navi.xy_to_screen_pos(pointer_t.to_timetable_time().to_ticks(), smoothed_logical_y);
    // stupid API here...
    stroke.round_center_to_pixel(ui.pixels_per_point(), &mut pos.x);
    stroke.round_center_to_pixel(ui.pixels_per_point(), &mut pos.y);
    ui.painter().hline(rect.x_range(), pos.y, stroke);
    ui.painter().vline(pos.x, rect.y_range(), stroke);
    ui.painter().text(
        pos + vec2(-3.0, -3.0),
        Align2::RIGHT_BOTTOM,
        pointer_t.to_timetable_time(),
        TIMETABLE_FONT_ID.clone(),
        ui.visuals().strong_text_color(),
    );
    ui.painter().text(
        pos + vec2(3.0, -3.0),
        Align2::LEFT_BOTTOM,
        "Double click to create trip",
        FontId::proportional(13.0),
        ui.visuals().strong_text_color(),
    );
    let station_name = route.intervals.0[station_idx]
        .station_record
        .station_key(app.graph.nodes())
        .and_then(|key| app.stations.get(key))
        .map_or("Unknown", |wfc| wfc.name.as_str());
    ui.painter().text(
        pos + vec2(-3.0, 3.0),
        Align2::RIGHT_TOP,
        station_name,
        FontId::proportional(13.0),
        ui.visuals().strong_text_color(),
    );
}
